player = input("あなたの手を入力してください: ")
computer = "グー"

if player == computer:
    print("あいこ")
elif player == "パー":
    print("あなたの勝ち")
elif player == "チョキ":
    print("あなたの負け")
else:
    print("グー・チョキ・パーを入力してください")

sales = [
    ("A", 1200),
    ("B", 900),
    ("A", 500)
]

summary = {}
for category, amount in sales:
    summary[category] = summary.get(category, 0) + amount

for category in sorted(summary.keys()):
    print(category, summary[category])
